    "summary": "Configuring Tailwind CSS v3.4+ alongside MotionFoundry design tokens and utility classes.",
    "body": "While `@motionfoundry/ui` components ship with self-contained CSS Modules so they work even without Tailwind CSS, the documentation site and optional Tailwind component variants use a restrained charcoal-black and graphite token palette.\n\n### Adding MotionFoundry Tokens to `tailwind.config.ts`\n\nExtend your `tailwind.config.ts` with our graphite surfaces, silver typography scale, and reduced-motion utilities.",
    "code": "import type { Config } from \"tailwindcss\";\n\nconst config: Config = {\n  darkMode: [\"class\"],\n  content: [\n    \"./app/**/*.{ts,tsx}\",\n    \"./components/**/*.{ts,tsx}\",\n    \"../../packages/ui/src/**/*.{ts,tsx}\",\n  ],\n  theme: {\n    extend: {\n      colors: {\n        charcoal: \"#09090B\",\n        graphite: \"#121216\",\n        surface: \"#18181F\",\n        borderSubtle: \"#24242C\",\n        silver: \"#F4F4F6\",\n        mutedSilver: \"#A1A1AA\",\n      },\n    },\n  },\n  plugins: [],\n};\n\nexport default config;"
